const MODE = 'delete';
const PROJECT = '691331356a3b9a68428ab3.43540470';
const KEY_NAME = 'about::zzTestAutomation::title';
const KEY_ID = '918137871';
const base = 'https://api.lokalise.com/api2/projects/' + PROJECT;
let method = 'GET';
let url = base + '/keys?limit=1';
let body = {};
if (MODE === 'create') {
  method = 'POST';
  url = base + '/keys';
  body = { keys: [ { key_name: KEY_NAME, platforms: ['web'], filenames: { web: 'locales/%LANG_ISO%.json' }, translations: [ { language_iso: 'en', translation: 'Meet the team behind Chatbot Online' } ] } ] };
} else if (MODE === 'inspect') {
  method = 'GET';
  url = base + '/keys/' + KEY_ID + '?include_screenshots=1';
} else if (MODE === 'delete') {
  method = 'DELETE';
  url = base + '/keys/' + KEY_ID;
}
return [{ json: { mode: MODE, project: PROJECT, method: method, url: url, body: body, sendBody: method === 'POST' } }];

const cfg = ($('Config').first().json) || {};
const r = ($input.first().json) || {};
const b = r.body || {};
const out = { mode: cfg.mode, status: r.statusCode, errors: b.errors || [] };
const keys = b.keys || [];
if (b.key) { keys.push(b.key); }
out.keys = [];
for (const k of keys) {
  const kn = k.key_name;
  out.keys.push({
    key_id: k.key_id,
    name: (typeof kn === 'string') ? kn : ((kn && (kn.web || kn.other)) || ''),
    tags: k.tags || [],
    description: k.description || '',
    screenshots: (k.screenshots || []).map(function (s) { return s.screenshot_id + ' ' + s.title; })
  });
}
if (b.key_removed !== undefined) { out.key_removed = b.key_removed; }
if (b.keys_locked !== undefined) { out.keys_locked = b.keys_locked; }
return [{ json: out }];
